class Solution {
public:
    long long countInterestingSubarrays(vector<int>& nums, int modulo, int k) {
        int n = (int)nums.size();
        unordered_map<long long, long long> mp;
        mp.reserve(n + 1);
        long long ans = 0;
        long long cnt = 0;
        mp[0] = 1;
        for (int i = 0; i < n; i++) {
            if (nums[i] % modulo == k) cnt++;
            long long cur = cnt % modulo;
            long long target = (cur - k + modulo) % modulo;
            auto it = mp.find(target);
            if (it != mp.end()) ans += it->second;
            mp[cur]++;
        }
        return ans;
    }
};
